with metrics as (select *, cume_dist() over (partition by product_id, store_id order by revenue asc nulls first) as revenue_cume_dist, dense_rank() over (partition by store_id order by units desc nulls last) as units_dense_rank from store_sales) select date_trunc('quarter', sale_date) as quarter_start, store_id, case when units >= 44 then 'LARGE' else 'SMALL' end as units_tier, count(*) as row_count, percentile_approx(revenue, array(0.25, 0.5, 0.75)) as revenue_quartiles, count(distinct store_id) as distinct_store_ids, avg(units) as avg_units, count(*) as cnt, round(avg(revenue_cume_dist), 2) as avg_revenue_cume_dist, dense_rank() over (partition by date_trunc('quarter', sale_date) order by avg(units) desc) as avg_units_dense_rank from metrics group by quarter_start, store_id, units_tier
